const { chromium } = require('D:/repository/门户/node_modules/playwright')

;(async () => {
  const browser = await chromium.launch()
  const ctx = await browser.newContext({ viewport: { width: 1920, height: 1080 }, deviceScaleFactor: 1 })
  const page = await ctx.newPage()
  const errors = []
  page.on('pageerror', (e) => errors.push(String(e)))
  await page.goto('http://127.0.0.1:8092/index.html#/market-monitor', { waitUntil: 'networkidle' })
  await page.waitForTimeout(1200)
  await page.locator('.mm-dashboard button', { hasText: '付款方式' }).first().click()
  await page.waitForTimeout(800)

