    const big = document.querySelectorAll('[class*="w-[172px]"]').length
    const small = document.querySelectorAll('[class*="w-[140px]"]').length
    const el = document.querySelector('[class*="w-[140px]"]')
    const r = el && el.getBoundingClientRect()
    return { bigBoxes: big, smallBoxes: small, box: r ? { w: r.width, h: r.height } : null }
  })
  console.log(JSON.stringify({ info, errors }))

  await page.screenshot({ path: 'D:/repository/门户/test-results/mm-pie-smaller-full.png' })
